'use client'

import * as React from 'react'
import { cn, collapsibleConnect, collapsibleMachine } from "@/lib/utils"
import { mergeProps, normalizeProps, useMachine } from '@zag-js/react'

import { Slot } from './slot'

const CollapsibleContext = React.createContext<{
  api: ReturnType<typeof collapsibleConnect>
} | null>(null)

function useCollapsible() {
  const context = React.useContext(CollapsibleContext)
  if (!context) {
    throw new Error('Collapsible components must be used within Collapsible')
  }
  return context
}

const Collapsible = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & {
    open?: boolean
    defaultOpen?: boolean
    onOpenChange?: (open: boolean) => void
    disabled?: boolean
  }
>(({ className, open, defaultOpen, onOpenChange, disabled, ...props }, ref) => {
  const service = useMachine(collapsibleMachine, {
    id: React.useId(),
    open,
    defaultOpen,
    disabled,
    onOpenChange(details) {
      onOpenChange?.(details.open)
    },
  })
  const api = React.useMemo(() => collapsibleConnect(service, normalizeProps), [service])
  const rootProps = api.getRootProps()
  const mergedProps = mergeProps(rootProps, props)

  return (
    <CollapsibleContext.Provider value={{ api }}>
      <div ref={ref} data-slot="collapsible" {...mergedProps} className={cn(className)} />
    </CollapsibleContext.Provider>
  )
})
Collapsible.displayName = 'Collapsible'

const CollapsibleTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }
>(({ className, asChild = false, ...props }, ref) => {
  const { api } = useCollapsible()
  const Comp = asChild ? Slot : 'button'
  const triggerProps = api.getTriggerProps()

  return (
    <Comp
      ref={ref}
      data-slot="collapsible-trigger"
      {...mergeProps(triggerProps, props)}
      className={cn(className)}
    />
  )
})
CollapsibleTrigger.displayName = 'CollapsibleTrigger'

const CollapsibleContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, children, ...props }, ref) => {
    const { api } = useCollapsible()
    const contentProps = api.getContentProps()
    const mergedProps = mergeProps(contentProps, props)

    return (
      <div
        ref={ref}
        data-slot="collapsible-content"
        className={cn('overflow-hidden', className)}
        {...mergedProps}
      >
        {children}
      </div>
    )
  }
)
CollapsibleContent.displayName = 'CollapsibleContent'

export { Collapsible, CollapsibleContent, CollapsibleTrigger }

import { type ComputedRef, inject, provide } from 'vue'
import type { CollapsibleApi } from "@/lib/utils"

export const CollapsibleContextKey = Symbol('CollapsibleContext')

export function provideCollapsibleContext(api: ComputedRef<CollapsibleApi>) {
    provide(CollapsibleContextKey, api)
}

export function useCollapsibleContext(): ComputedRef<CollapsibleApi> {
    const context = inject<ComputedRef<CollapsibleApi>>(CollapsibleContextKey)
    if (!context) {
        throw new Error('useCollapsibleContext must be used within a CollapsibleProvider')
    }
    return context
}

import { computed } from 'vue'
import { collapsibleMachine, collapsibleConnect } from "@/lib/utils"
import { useMachine, normalizeProps } from '@zag-js/vue'

type CollapsibleProps = {
    id?: string
    open?: boolean
    defaultOpen?: boolean
    disabled?: boolean
    onOpenChange?: (details: { open: boolean }) => void
}

export function useCollapsible(props: CollapsibleProps = {}) {
    const service = useMachine(collapsibleMachine, {
        id: props.id,
        open: props.open,
        defaultOpen: props.defaultOpen,
        disabled: props.disabled,
        onOpenChange: props.onOpenChange,
    })

    return computed(() => collapsibleConnect(service, normalizeProps))
}

import { setupCollapsibleMachine } from './use-collapsible'

type MachineEvent = string | {
    type: string
    [key: string]: string | number | boolean | string[] | number[] | null | undefined
}

type WeappCollapsibleApi = {
    open?: () => void
    close?: () => void
    triggerProps?: {
        onClick?: () => void
    }
}

type WeappService = {
    setContext: (context: {
        open?: boolean
        disabled?: boolean
    }) => void
}

type WeappCollapsibleInternal = WechatMiniprogram.Component.InstanceMethods<WechatMiniprogram.IAnyObject> & {
    _service?: WeappService
    _cleanup?: () => void
    _send?: (event: MachineEvent) => void
    data: {
        api: WeappCollapsibleApi
    }
    properties: {
        open: boolean
        disabled: boolean
        id: string
        extClass: string
    }
}

Component({
    options: {
        styleIsolation: 'apply-shared',
        pureDataPattern: /^_/,
    },

    properties: {
        open: { type: Boolean, value: false },
        disabled: { type: Boolean, value: false },
        id: { type: String, value: 'collapsible' },
        extClass: { type: String, value: '' },
    },

    data: {
        api: {} as WeappCollapsibleApi,
        className: '',
    },

    lifetimes: {
        attached() {
            const self = this as WeappCollapsibleInternal
            const { service, cleanup, send } = setupCollapsibleMachine(this, {
                id: this.properties.id,
                open: this.properties.open,
                disabled: this.properties.disabled,
                onOpenChange: (details) => {
                    this.triggerEvent('change', details)
                }
            })

            self._service = service as WeappService
            self._cleanup = cleanup
            self._send = send as (event: MachineEvent) => void
        },
        detached() {
            const self = this as WeappCollapsibleInternal
            self._cleanup?.()
        },
    },

    observers: {
        'state': function (state) {
            const self = this as WeappCollapsibleInternal
            if (!state || !self._send) return
            const { connect } = setupCollapsibleMachine(this, { id: this.properties.id })
            const api = connect(state, self._send) as WeappCollapsibleApi
            this.setData({ api, className: this.properties.extClass })
        },

        'open': function (val) {
            const self = this as WeappCollapsibleInternal
            if (self._service) {
                if (val) {
                    self.data.api.open?.()
                } else {
                    self.data.api.close?.()
                }
            }
        },
    },

    methods: {
        onTriggerTap() {
            const self = this as WeappCollapsibleInternal
            self.data.api.triggerProps?.onClick?.()
        },
    },
})
